package io.github.supermonster003.autojs6.plugin.batch.rename.engine.pinyin

import java.io.InputStream

/**
 * The built-in pinyin dictionary (roadmap D35): the customary reading of every character, the phrases whose readings
 * differ from those of their characters, and traditional to simplified characters for looking up phrases. The files are
 * Java resources under `pinyin/` generated by `.python/generate_pinyin_dictionary.py` from `third_party/`.
 * zh-CN: 内置拼音词典 (路线图 D35): 每个汉字的常用读音, 读音与逐字读音不同的词组, 以及用于查词组的繁体到简体单字映射. 文件为
 * `pinyin/` 下的 Java 资源, 由 `.python/generate_pinyin_dictionary.py` 从 `third_party/` 生成.
 */
internal class PinyinDictionary private constructor(
    /** Code points in ascending order. zh-CN: 升序码点. */
    private val codePoints: IntArray,
    private val readings: Array<String>,
    private val phrases: Map<String, List<String>>,
    private val traditional: IntArray,
    private val simplified: IntArray,
) {

    /** Characters of the longest phrase. zh-CN: 最长词组的字数. */
    val maxPhraseLength: Int = phrases.keys.maxOfOrNull { it.codePointCount(0, it.length) } ?: 0

    /** The customary reading with tone marks, or null for a character without one. zh-CN: 带声调符号的常用读音. */
    fun reading(codePoint: Int): String? {
        val index = codePoints.binarySearch(codePoint)
        return if (index >= 0) readings[index] else null
    }

    /** The simplified form of a traditional character, or the character itself. zh-CN: 繁体字的简体形式, 否则为原字. */
    fun simplify(codePoint: Int): Int {
        val index = traditional.binarySearch(codePoint)
        return if (index >= 0) simplified[index] else codePoint
    }

    /** The syllables of a simplified phrase, or null. zh-CN: 简体词组的音节, 或 null. */
    fun phrase(text: String): List<String>? = phrases[text]

    companion object {

        const val FORMAT = 1

        private const val HEADER = "# Batch Rename pinyin dictionary format $FORMAT,"

        /** Loaded on first use; about 670 KB of text. zh-CN: 首次使用时加载, 文本约 670 KB. */
        val default: PinyinDictionary by lazy { load { name -> PinyinDictionary::class.java.getResourceAsStream("/pinyin/$name") } }

        /**
         * @throws IllegalStateException when a file is missing or does not carry the expected format.
         */
        fun load(open: (String) -> InputStream?): PinyinDictionary {
            val syllables = HashMap<String, String>()
            fun syllable(text: String) = syllables.getOrPut(text) { text }

            val characters = entries(open, "chars.txt")
            val codePoints = IntArray(characters.size)
            val readings = Array(characters.size) { index ->
                val (key, value) = characters[index]
                codePoints[index] = key.codePointAt(0)
                check(index == 0 || codePoints[index - 1] < codePoints[index]) { "chars.txt is not sorted at \"$key\"" }
                syllable(value)
            }
            val phrases = HashMap<String, List<String>>()
            entries(open, "phrases.txt").forEach { (key, value) -> phrases[key] = value.split(' ').map(::syllable) }
            val pairs = entries(open, "t2s.txt")
            val traditional = IntArray(pairs.size) { pairs[it].first.codePointAt(0) }
            val simplified = IntArray(pairs.size) { pairs[it].second.codePointAt(0) }
            check((1 until traditional.size).all { traditional[it - 1] < traditional[it] }) { "t2s.txt is not sorted" }
            return PinyinDictionary(codePoints, readings, phrases, traditional, simplified)
        }

        private fun entries(open: (String) -> InputStream?, name: String): List<Pair<String, String>> {
            val stream = open(name) ?: throw IllegalStateException("The pinyin dictionary lacks $name")
            val lines = stream.bufferedReader(Charsets.UTF_8).use { it.readLines() }
            check(lines.firstOrNull()?.startsWith(HEADER) == true) { "$name is not a pinyin dictionary of format $FORMAT" }
            return lines.drop(1).map { line ->
                val tab = line.indexOf('\t')
                check(tab > 0 && tab < line.length - 1) { "$name holds the malformed line \"$line\"" }
                line.substring(0, tab) to line.substring(tab + 1)
            }
        }
    }
}
